#[derive(Debug, Clone, PartialEq, serde::Serialize, serde::Deserialize, Eq, std::hash::Hash)]
#[serde(tag = "_variant")]
pub enum ConcreteSyntaxToken {
    FixedToken {
        token_class: Symbol,
    },
    BoundToken {
        token_class: Symbol,
        binding: Symbol,
    },
}
impl ConcreteSyntaxToken {
    pub fn token_class(&self) -> Symbol {
        match self {
            ConcreteSyntaxToken::FixedToken { token_class: __val, .. } => __val.clone(),
            ConcreteSyntaxToken::BoundToken { token_class: __val, .. } => __val.clone(),
        }
    }
}

