pub fn lex_rule_fixed_spelling(rule: Rc<LexRule>, token_class: std::string::String) -> Option<String> {
    match (*rule.clone()).clone() {
    LexRule::TokenRule { token_class: c, pattern, .. } => if (c.clone() == token_class.clone()) {
        lex_pattern_fixed_spelling(pattern.clone())
    } else {
        crate::std_optional::optional_absent()
    },
    LexRule::ModeTransitionTokenRule { token_class: c, pattern, .. } => if (c.clone() == token_class.clone()) {
        lex_pattern_fixed_spelling(pattern.clone())
    } else {
        crate::std_optional::optional_absent()
    },
    LexRule::TriviaRule { pattern: _, .. } => crate::std_optional::optional_absent(),
    LexRule::AnnotationRule { .. } => crate::std_optional::optional_absent(),
}
}

pub fn lex_pattern_fixed_spelling(pattern: Rc<LexPattern>) -> Option<String> {
    match (*pattern.clone()).clone() {
    LexPattern::LiteralPattern { text: text, .. } => crate::std_optional::optional_present(crate::std_coercion::unicode_scalar_fold(text.clone())),
    LexPattern::KeywordPattern { text: text, .. } => crate::std_optional::optional_present(crate::std_coercion::unicode_scalar_fold(text.clone())),
    LexPattern::EmptyPattern => crate::std_optional::optional_absent(),
    LexPattern::CharPattern { char: _, .. } => crate::std_optional::optional_absent(),
    LexPattern::CharClassPattern { class: _, .. } => crate::std_optional::optional_absent(),
    LexPattern::SequencePattern { .. } => crate::std_optional::optional_absent(),
    LexPattern::ChoicePattern { .. } => crate::std_optional::optional_absent(),
    LexPattern::OptionalPattern { element: _, .. } => crate::std_optional::optional_absent(),
    LexPattern::RepeatPattern { element: _, .. } => crate::std_optional::optional_absent(),
    LexPattern::OneOrMorePattern { element: _, .. } => crate::std_optional::optional_absent(),
    LexPattern::DelimitedPattern { .. } => crate::std_optional::optional_absent(),
    LexPattern::NotFollowedByPattern { element: _, .. } => crate::std_optional::optional_absent(),
}
}

