pub fn text_atom(lexeme: String) -> Rc<TargetText> {
    Rc::new(TargetText {
    parts: Rc::new(vec![Rc::new(Doc::DocText {
    text: lexeme.clone(),
})]),
    empty: (lexeme.clone() == "".to_string()),
})
}

pub fn target_text_seq(acc: Rc<TargetText>, next: Rc<TargetText>) -> Rc<TargetText> {
    { let __rb_0_0 = crate::std_algebra::list_snoc_item(acc.parts.clone(), Rc::new(Doc::DocConcat {
    parts: next.parts.clone(),
})); let __rb_1_0 = (acc.empty.clone() && next.empty.clone()); let mut __rb_h = next; match Rc::get_mut(&mut __rb_h) { Some(__rb_r) => { __rb_r.parts = __rb_0_0; __rb_r.empty = __rb_1_0; } None => { __rb_h = Rc::new(TargetText { parts: __rb_0_0, empty: __rb_1_0 }); } } __rb_h }
}

pub fn target_text_nested(unit: String, body: Rc<TargetText>) -> Rc<TargetText> {
    { let __rb_0_0 = Rc::new(vec![crate::std_layout::doc_nest_by(unit, Rc::new(Doc::DocConcat {
    parts: body.parts.clone(),
}))]); let __rb_1_0 = body.empty.clone(); let mut __rb_h = body; match Rc::get_mut(&mut __rb_h) { Some(__rb_r) => { __rb_r.parts = __rb_0_0; __rb_r.empty = __rb_1_0; } None => { __rb_h = Rc::new(TargetText { parts: __rb_0_0, empty: __rb_1_0 }); } } __rb_h }
}

pub fn target_text_line_breaks(before: i64, lexeme: String, after: i64) -> Rc<TargetText> {
    Rc::new(TargetText {
    parts: crate::std_algebra::list_append(crate::std_algebra::list_append(repeat_line(before.clone()), Rc::new(vec![Rc::new(Doc::DocText {
    text: lexeme.clone(),
})])), repeat_line(after.clone())),
    empty: (((before.clone() <= 0) && (after.clone() <= 0)) && (lexeme.clone() == "".to_string())),
})
}

pub fn repeat_line(n: i64) -> Rc<Vec<Rc<Doc>>> {
    stacker::maybe_grow(512 * 1024, 2 * 1024 * 1024, || {
        if (n.clone() <= 0) {
            Rc::new(vec![])
        } else {
            crate::std_algebra::list_snoc_item(repeat_line(v1_rt::int_sub(n.clone(), 1)), Rc::new(Doc::DocLine))
        }
    })
}

pub fn render_target_text(t: Rc<TargetText>) -> String {
    crate::std_layout::render(Rc::new(Doc::DocConcat {
    parts: t.parts.clone(),
}), target_text_render_protocol())
}

