pub fn bound_tokens_source_text_with_transforms(tokens: Rc<Vec<Rc<ConcreteSyntaxToken>>>, lex: Rc<LexRules>, binding_spellings: Rc<HashMap<Symbol, String>>, transforms: Rc<HashMap<Symbol, Rc<TokenClassEmitTransform>>>) -> Rc<Outcome<Rc<TargetText>>> {
    crate::std_algebra::fold_list(tokens, Rc::new(Outcome::Accepted {
    value: target_text_empty(),
    diagnostics: Box::new(std::option::Option::None),
}), |acc, token| match (*acc.clone()).clone() {
    Outcome::Rejected { diagnostics: r, .. } => Rc::new(Outcome::Rejected {
    diagnostics: r.clone(),
}),
    Outcome::Accepted { value: partial, diagnostics: ref __rc_diagnostics, .. } => { let ad = __rc_diagnostics.as_ref(); match (*token.clone()).clone() {
    ConcreteSyntaxToken::FixedToken { token_class: tc, .. } => crate::v2_std_diagnostic::bind_outcome(lex_rules_literal_for_class(lex.clone(), tc.clone()), |spelling| crate::v2_std_diagnostic::bind_outcome(layout_or_atom_in(transforms.clone(), tc.clone(), spelling), |text| Rc::new(Outcome::Accepted {
    value: target_text_seq(partial.clone(), text),
    diagnostics: Box::new(ad.clone()),
}))),
    ConcreteSyntaxToken::BoundToken { token_class: tc, binding: b, .. } => crate::v2_std_diagnostic::bind_outcome(bound_spelling_from_map(binding_spellings.clone(), b.clone()), |spelling| crate::v2_std_diagnostic::bind_outcome(layout_or_atom_in(transforms.clone(), tc.clone(), spelling), |text| Rc::new(Outcome::Accepted {
    value: target_text_seq(partial.clone(), text),
    diagnostics: Box::new(ad.clone()),
}))),
} },
})
}

pub fn bound_tokens_source_text(tokens: Rc<Vec<Rc<ConcreteSyntaxToken>>>, lex: Rc<LexRules>, binding_spellings: Rc<HashMap<Symbol, String>>) -> Rc<Outcome<Rc<TargetText>>> {
    bound_tokens_source_text_with_transforms(tokens, lex, binding_spellings, target_model_emit_transforms_empty())
}

