pub fn apply_emit_spelling_escapes(spelling: Rc<Vec<i64>>, escapes: Rc<Vec<Rc<EmitSpellingEscape>>>) -> Rc<Vec<i64>> {
    crate::std_algebra::fold_list(escapes, spelling, |acc, rule| { let __fm = rule.from.clone(); if __fm.len() >= 1 { let h = (*__fm)[0].clone(); let t: Rc<Vec<_>> = Rc::new(__fm.skip(1)); crate::v2_std_text::string_replace(acc, Rc::new(FreeSemigroup {
    head: h.clone(),
    tail: t.clone(),
    _phantom: std::marker::PhantomData,
}), rule.to.clone()) } else { acc.clone() } })
}

