pub fn apply_emit_spelling_transform(transform: Rc<TokenClassEmitTransform>, token_class: std::string::String, spelling: String) -> Rc<Outcome<String>> {
    match (*transform.clone()).clone() {
    TokenClassEmitTransform::EmitSpellingIdentity => crate::v2_std_diagnostic::outcome_accepted(spelling.clone()),
    TokenClassEmitTransform::EmitSpellingConstant { value: v, .. } => crate::v2_std_diagnostic::outcome_accepted(v.clone()),
    TokenClassEmitTransform::EmitSpellingWrap { prefix: p, suffix: s, .. } => crate::v2_std_diagnostic::outcome_accepted(v1_rt::concat(p.clone(), v1_rt::concat(spelling.clone(), s.clone()))),
    TokenClassEmitTransform::EmitSpellingQuote { prefix: p, open: o, close: c, escapes: es, .. } => crate::v2_std_diagnostic::outcome_accepted(apply_emit_spelling_quote(p.clone(), o.clone(), c.clone(), es.clone(), spelling.clone())),
    TokenClassEmitTransform::EmitLineBreaks { .. } => crate::v2_std_diagnostic::outcome_rejected(target_layout_token_spelled_flat_diagnostic(token_class)),
}
}

