pub fn ordering_predicate_accepts(predicate: OrderingPredicate) -> Rc<Vec<Ordering>> {
    match predicate.clone() {
    OrderingPredicate::IsLess => Rc::new(vec![Ordering::Less]),
    OrderingPredicate::IsLessOrEqual => Rc::new(vec![Ordering::Less, Ordering::Equal]),
    OrderingPredicate::IsGreater => Rc::new(vec![Ordering::Greater]),
    OrderingPredicate::IsGreaterOrEqual => Rc::new(vec![Ordering::Equal, Ordering::Greater]),
}
}

pub fn equality_predicate_accepts(predicate: EqualityPredicate) -> bool {
    match predicate.clone() {
    EqualityPredicate::IsEqual => true,
    EqualityPredicate::IsNotEqual => false,
}
}

