pub fn derive_bodied_arrow_scaffold(signature_with_open: Rc<Vec<Rc<ConcreteSyntaxToken>>>, block_close: Rc<Vec<Rc<ConcreteSyntaxToken>>>, mode: Rc<BlockEvaluationMode>) -> Rc<TargetBodiedArrowStatementScaffold> {
    match (*mode.clone()).clone() {
    BlockEvaluationMode::ValueProducing => Rc::new(TargetBodiedArrowStatementScaffold {
    prefix: signature_with_open.clone(),
    suffix: block_close.clone(),
}),
    BlockEvaluationMode::StatementSequenced { return_token, statement_terminator, .. } => Rc::new(TargetBodiedArrowStatementScaffold {
    prefix: crate::std_algebra::list_snoc_item(signature_with_open.clone(), Rc::new(ConcreteSyntaxToken::FixedToken {
    token_class: return_token.clone(),
})),
    suffix: crate::std_algebra::list_append(Rc::new(vec![Rc::new(ConcreteSyntaxToken::FixedToken {
    token_class: statement_terminator.clone(),
})]), block_close.clone()),
}),
}
}

