#[derive(Debug, Clone, PartialEq, serde::Serialize)]
#[serde(tag = "_variant")]
pub enum TargetCollectionRealizationLookup {
    TargetCollectionRealizationMissing,
    TargetCollectionRealizationUnique {
        row: Rc<TargetCollectionRealization>,
    },
    TargetCollectionRealizationAmbiguous,
}
impl TargetCollectionRealizationLookup {
    pub fn row(&self) -> Rc<TargetCollectionRealization> {
        match self {
            TargetCollectionRealizationLookup::TargetCollectionRealizationMissing => panic!("no row on unit variant"),
            TargetCollectionRealizationLookup::TargetCollectionRealizationUnique { row: __val, .. } => __val.clone(),
            TargetCollectionRealizationLookup::TargetCollectionRealizationAmbiguous => panic!("no row on unit variant"),
        }
    }
}

pub fn target_collection_realization_lookup_step(acc: Rc<TargetCollectionRealizationLookup>, row: Rc<TargetCollectionRealization>, source_carrier: Rc<Node>) -> Rc<TargetCollectionRealizationLookup> {
    if (crate::v2_std_node::content_hash(row.source_carrier.clone()) == crate::v2_std_node::content_hash(source_carrier)) {
        match (*acc.clone()).clone() {
    TargetCollectionRealizationLookup::TargetCollectionRealizationMissing => Rc::new(TargetCollectionRealizationLookup::TargetCollectionRealizationUnique {
    row: row.clone(),
}),
    TargetCollectionRealizationLookup::TargetCollectionRealizationUnique { row: _, .. } => Rc::new(TargetCollectionRealizationLookup::TargetCollectionRealizationAmbiguous),
    TargetCollectionRealizationLookup::TargetCollectionRealizationAmbiguous => Rc::new(TargetCollectionRealizationLookup::TargetCollectionRealizationAmbiguous),
}
    } else {
        acc.clone()
    }
}

pub fn target_collection_realization_lookup_in_catalog(catalog: Rc<Vec<Rc<TargetCollectionRealization>>>, source_carrier: Rc<Node>) -> Rc<Outcome<Rc<TargetCollectionRealization>>> {
    match (*crate::std_algebra::fold_list(catalog, Rc::new(TargetCollectionRealizationLookup::TargetCollectionRealizationMissing), |acc, row| target_collection_realization_lookup_step(acc, row, source_carrier.clone()))).clone() {
    TargetCollectionRealizationLookup::TargetCollectionRealizationMissing => crate::v2_std_diagnostic::outcome_rejected(target_collection_realization_lookup_miss_diagnostic(source_carrier.clone())),
    TargetCollectionRealizationLookup::TargetCollectionRealizationUnique { row: row, .. } => crate::v2_std_diagnostic::outcome_accepted(row.clone()),
    TargetCollectionRealizationLookup::TargetCollectionRealizationAmbiguous => crate::v2_std_diagnostic::outcome_rejected(target_collection_realization_lookup_ambiguous_diagnostic(source_carrier.clone())),
}
}

