#[derive(Debug, Clone, Copy, PartialEq, Eq, PartialOrd, Ord, serde::Serialize, serde::Deserialize)]
#[serde(tag = "_variant")]
pub enum TargetReferenceLayerWrapped {
    WrappedReferenceLayerRc,
    WrappedReferenceLayerBox,
}

#[derive(Debug, Clone, PartialEq, serde::Serialize, serde::Deserialize)]
#[serde(tag = "_variant")]
pub enum TargetReferenceLayerProbe {
    ReferenceLayerProbe {
        value: TargetReferenceLayerWrapped,
    },
    ReferenceLayerProbeNotWrapped,
    ReferenceLayerProbeInvalid,
}
impl TargetReferenceLayerProbe {
    pub fn value(&self) -> TargetReferenceLayerWrapped {
        match self {
            TargetReferenceLayerProbe::ReferenceLayerProbe { value: __val, .. } => __val.clone(),
            TargetReferenceLayerProbe::ReferenceLayerProbeNotWrapped => panic!("no value on unit variant"),
            TargetReferenceLayerProbe::ReferenceLayerProbeInvalid => panic!("no value on unit variant"),
        }
    }
}

pub fn target_reference_layer_probe_from_emitted_type(emitted: Rc<Node>, projection: Rc<TargetTypeExpressionProjection>, tokens: Rc<TargetReferenceLayerTokens>) -> Rc<TargetReferenceLayerProbe> {
    match (*target_type_expr_emitted_wire_decode(emitted.clone(), projection)).clone() {
    Outcome::Accepted { value: wire, .. } => match wire.kind.clone() {
    TargetTypeExprKind::TargetTypeExprInstantiation => match v1_rt::list_get_optional(&crate::v2_std_node::positional_child_target_nodes(wire.node.clone()), 0) {
    Some(head) => match (*target_model_node_atom_identity(head.clone(), emitted.clone())).clone() {
    Outcome::Accepted { value: head_id, .. } => if (head_id.clone() == tokens.rc_type_head.clone()) {
        Rc::new(TargetReferenceLayerProbe::ReferenceLayerProbe {
    value: TargetReferenceLayerWrapped::WrappedReferenceLayerRc,
})
    } else {
        if (head_id.clone() == tokens.box_type_head.clone()) {
            Rc::new(TargetReferenceLayerProbe::ReferenceLayerProbe {
    value: TargetReferenceLayerWrapped::WrappedReferenceLayerBox,
})
        } else {
            Rc::new(TargetReferenceLayerProbe::ReferenceLayerProbeNotWrapped)
        }
    },
    Outcome::Rejected { diagnostics: _, .. } => Rc::new(TargetReferenceLayerProbe::ReferenceLayerProbeInvalid),
},
    std::option::Option::None => Rc::new(TargetReferenceLayerProbe::ReferenceLayerProbeInvalid),
},
    TargetTypeExprKind::TargetTypeExprAtom => Rc::new(TargetReferenceLayerProbe::ReferenceLayerProbeNotWrapped),
    TargetTypeExprKind::TargetTypeExprOptionalInstantiation => Rc::new(TargetReferenceLayerProbe::ReferenceLayerProbeNotWrapped),
    TargetTypeExprKind::TargetTypeExprRecord => Rc::new(TargetReferenceLayerProbe::ReferenceLayerProbeNotWrapped),
    TargetTypeExprKind::TargetTypeExprSum => Rc::new(TargetReferenceLayerProbe::ReferenceLayerProbeNotWrapped),
    TargetTypeExprKind::TargetTypeExprArrow => Rc::new(TargetReferenceLayerProbe::ReferenceLayerProbeNotWrapped),
},
    Outcome::Rejected { diagnostics: _, .. } => Rc::new(TargetReferenceLayerProbe::ReferenceLayerProbeInvalid),
}
}

